export function getSkillsCatalog() {
  return SKILLS_CATALOG;
}

export function getSkillBySlug(slug) {
  if (!slug) return null;
  return SKILLS_CATALOG.find(s => s.slug === slug || s.name === slug) || null;
}

export function findSkillsByKeyword(query) {
  if (!query) return SKILLS_CATALOG;
  const q = query.toLowerCase();
  return SKILLS_CATALOG.filter(s =>
    s.name.toLowerCase().includes(q) ||
    s.description.toLowerCase().includes(q) ||
    s.category.toLowerCase().includes(q) ||
    s.tags.some(t => t.toLowerCase().includes(q))
  );
}
